:root {
  --surface: #ffffff;
  --ink: #26332d;
  --accent: #e66a4e;
}

.route-ready {
  width: 440px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--ink);
  border-left: 6px solid var(--accent);
  border-radius: 12px;
  color: var(--ink);
}

.route-icon {
  color: var(--accent);
  font-size: 24px;
  line-height: 1;
}

.route-copy h2 {
  margin: 0;
  font-size: 18px;
  line-height: 1.1;
}

.route-copy p {
  margin: 4px 0 0;
  font-size: 14px;
}

.grade {
  margin-left: auto;
  padding: 5px 9px;
  background: var(--accent);
  border-radius: 999px;
  color: var(--surface);
  font-size: 13px;
  font-weight: 700;
}
